/// Advances an explicitly started ADR 0156 campaign on controlled fixture Editors.
///
/// The worker uses a separate fixture project, AgentHost, MCP endpoint, and normal EditorApp
/// runtime surface. It never borrows the user's active project as benchmark input.
pub fn advance_benchmark_campaign(
    &mut self,
    context: &egui::Context,
    frame: &mut eframe::Frame,
) {
    let Some(state) = self.benchmark_campaign.as_ref().map(|campaign| campaign.state) else {
        return;
    };
    if state != BenchmarkCampaignState::Running && self.benchmark_worker.is_none() {
        return;
    }

    if self.benchmark_worker.is_none() {
        let interrupted = self
            .benchmark_campaign
            .as_ref()
            .and_then(|campaign| campaign.running_run_request().transpose())
            .transpose();
        match interrupted {
            Ok(Some(request)) => {
                let result = match self.benchmark_campaign.as_mut() {
                    Some(campaign) => campaign
                        .fail_measured_run(&request, CampaignFailureKind::Cancelled),
                    None => Err("Campaign disappeared.".to_owned()),
                }
                .and_then(|()| self.persist_benchmark_campaign());
                self.status = Some(match result {
                    Ok(()) => format!(
                        "Recovered interrupted measured campaign run {} as failed evidence; it was not retried.",
                        request.schedule.ordinal
                    ),
                    Err(error) => error,
                });
                context.request_repaint();
                return;
            }
            Ok(None) => {}
            Err(error) => {
                self.status = Some(error);
                return;
            }
        }

        let request = {
            let Some(campaign) = self.benchmark_campaign.as_mut() else {
                return;
            };
            match campaign.preparing_run_request() {
                Ok(Some(request)) => Some(request),
                Ok(None) => match campaign.begin_next_run() {
                    Ok(request) => request,
                    Err(error) => {
                        self.status = Some(error);
                        return;
                    }
                },
                Err(error) => {
                    self.status = Some(error);
                    return;
                }
            }
        };
        if let Err(error) = self.persist_benchmark_campaign() {
            self.status = Some(error);
            return;
        }
        let Some(request) = request else {
            self.status = Some("Benchmark campaign completed its frozen schedule.".to_owned());
            return;
        };

        let inventory = match self.current_installed_inventory().cloned() {
            Some(inventory) => inventory,
            None => {
                self.record_campaign_preparation_failure(
                    &request,
                    "Installed-model inventory is unavailable for exact run verification.",
                );
                return;
            }
        };
        let observed = model_identity(
            &request.model.backend_id,
            &request.model.model_id,
            Some(&inventory),
        );
        if observed != request.model {
            self.record_campaign_preparation_failure(
                &request,
                "Exact model representation drifted before measured execution.",
            );
            return;
        }

        let (quality, hardware, profile) = match self.benchmark_campaign.as_ref() {
            Some(campaign) => (
                campaign.plan.quality,
                campaign.plan.hardware.clone(),
                campaign.plan.execution_profile,
            ),
            None => return,
        };
        let fixtures_root = dirs::data_local_dir()
            .unwrap_or_else(std::env::temp_dir)
            .join("GameEngine")
            .join("ai")
            .join("benchmark-fixtures");
        match BenchmarkCampaignWorker::new(
            context,
            &fixtures_root,
            request.clone(),
            inventory,
            quality,
            hardware,
            profile,
        ) {
            Ok(worker) => {
                self.benchmark_worker = Some(Box::new(worker));
                self.status = Some(format!(
                    "Preparing controlled fixture run {}/{}: {} · repetition {}.",
                    request.schedule.ordinal + 1,
                    self.benchmark_campaign
                        .as_ref()
                        .map(|campaign| campaign.runs.len())
                        .unwrap_or_default(),
                    request.schedule.task_id,
                    request.schedule.repetition,
                ));
            }
            Err(error) => {
                self.record_campaign_preparation_failure(&request, &error);
                return;
            }
        }
    }

    let Some(mut worker) = self.benchmark_worker.take() else {
        return;
    };
    match worker.poll_preparation(context) {
        Ok(BenchmarkWorkerPreparation::Pending) => {
            self.benchmark_worker = Some(worker);
            return;
        }
        Ok(BenchmarkWorkerPreparation::Ready) => {}
        Err(error) => {
            let request = worker.request.clone();
            self.record_campaign_preparation_failure(&request, &error);
            return;
        }
    }

    if !worker.measured_started {
        let request = worker.request.clone();
        let marked = match self.benchmark_campaign.as_mut() {
            Some(campaign) => campaign.mark_measurement_started(&request),
            None => Err("Campaign disappeared.".to_owned()),
        }
        .and_then(|()| self.persist_benchmark_campaign());
        if let Err(error) = marked {
            self.status = Some(error);
            return;
        }
        if let Err(error) = worker.start_measured() {
            let failure = classify_campaign_failure(&error, CampaignFailureKind::Other);
            let result = match self.benchmark_campaign.as_mut() {
                Some(campaign) => campaign.fail_measured_run(&request, failure),
                None => Err("Campaign disappeared.".to_owned()),
            }
            .and_then(|()| self.persist_benchmark_campaign());
            self.status = Some(match result {
                Ok(()) => format!(
                    "Measured campaign run {} failed while starting: {error}",
                    request.schedule.ordinal
                ),
                Err(persist_error) => persist_error,
            });
            context.request_repaint();
            return;
        }
    }

    let request = worker.request.clone();
    match worker.tick(context, frame) {
        Ok(BenchmarkWorkerOutcome::Pending) => {
            self.benchmark_worker = Some(worker);
            context.request_repaint_after(std::time::Duration::from_millis(50));
        }
        Ok(outcome) => {
            self.finish_benchmark_worker(&request, outcome);
            context.request_repaint();
        }
        Err(error) => {
            let failure = classify_campaign_failure(&error, CampaignFailureKind::Other);
            let result = match self.benchmark_campaign.as_mut() {
                Some(campaign) => campaign.fail_measured_run(&request, failure),
                None => Err("Campaign disappeared.".to_owned()),
            }
            .and_then(|()| self.persist_benchmark_campaign());
            self.status = Some(match result {
                Ok(()) => format!(
                    "Measured campaign run {} failed: {error}",
                    request.schedule.ordinal
                ),
                Err(persist_error) => persist_error,
            });
            context.request_repaint();
        }
    }
}

fn record_campaign_preparation_failure(
    &mut self,
    request: &CampaignRunRequest,
    message: &str,
) {
    let disposition = match self.benchmark_campaign.as_mut() {
        Some(campaign) => campaign.record_pre_measurement_failure(request),
        None => Err("Campaign disappeared.".to_owned()),
    };
    let result = disposition.and_then(|disposition| {
        self.persist_benchmark_campaign()?;
        Ok(disposition)
    });
    self.status = Some(match result {
        Ok(PreMeasurementFailureDisposition::Retry) => format!(
            "Campaign preparation failed before measurement and will retry within the bounded infrastructure budget: {message}"
        ),
        Ok(PreMeasurementFailureDisposition::Exhausted) => format!(
            "Campaign preparation exhausted its bounded pre-measurement retry budget: {message}"
        ),
        Err(error) => error,
    });
}

fn finish_benchmark_worker(
    &mut self,
    request: &CampaignRunRequest,
    outcome: BenchmarkWorkerOutcome,
) {
    let result = match outcome {
        BenchmarkWorkerOutcome::Pending => return,
        BenchmarkWorkerOutcome::Succeeded(record) => match self.benchmark_campaign.as_mut() {
            Some(campaign) => campaign.complete_run(request, record),
            None => Err("Campaign disappeared.".to_owned()),
        },
        BenchmarkWorkerOutcome::Failed { failure, record } => {
            match self.benchmark_campaign.as_mut() {
                Some(campaign) => {
                    campaign.fail_measured_run_with_record(request, failure, record)
                }
                None => Err("Campaign disappeared.".to_owned()),
            }
        }
    };
    if let Err(error) = result {
        self.status = Some(error);
        let _ = self.persist_benchmark_campaign();
        return;
    }

    let record = self
        .benchmark_campaign
        .as_ref()
        .and_then(|campaign| campaign.runs.get(request.schedule.ordinal as usize))
        .and_then(|run| run.record.clone());
    if let Err(error) = self.persist_benchmark_campaign() {
        self.status = Some(error);
        return;
    }
    if let Some(record) = record {
        if let Err(error) = self.benchmark_store.record(&record) {
            self.status = Some(format!(
                "Campaign progress was saved, but ADR 0142 evidence storage failed: {error}"
            ));
            return;
        }
        if let Err(error) = self.refresh_benchmark_catalog() {
            self.status = Some(format!(
                "Campaign evidence was stored, but catalog refresh failed: {error}"
            ));
            return;
        }
    }
    self.status = Some(format!(
        "Finished campaign run {} ({}, repetition {}).",
        request.schedule.ordinal,
        request.schedule.task_id,
        request.schedule.repetition,
    ));
}

